import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseInt("")
    match a {
        Some(v) => { io.println("i-bad ${v}") }
        None => { io.println("i-none") }
    }
    let b = string.parseUInt("")
    match b {
        Some(v) => { io.println("u-bad ${v}") }
        None => { io.println("u-none") }
    }
    let c = string.parseFloat("")
    match c {
        Some(v) => { io.println("f-bad ${v}") }
        None => { io.println("f-none") }
    }
    return Ok(())
}
